package local.personalmemo.graph.api;
import java.util.*; import local.personalmemo.common.DevIdentity; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/graph") public class GraphController {private final JdbcClient db;private final DevIdentity identity;public GraphController(JdbcClient d,DevIdentity i){db=d;identity=i;}
 @GetMapping("/home") Map<String,Object> home(@RequestParam(defaultValue="100") int limit){int bounded=Math.max(1,Math.min(limit,100));var nodes=new ArrayList<Map<String,Object>>();var edges=new ArrayList<Map<String,Object>>();db.sql("select distinct m.id,i.title,i.kind,t.status,(t.status='TODO' and t.due_at_utc is not null and t.due_at_utc<now()) overdue from memos m join memo_items i on i.memo_id=m.id left join task_details t on t.memo_item_id=i.id where m.owner_id=:o and m.status='ACTIVE' order by m.id limit :l").param("o",identity.ownerId()).param("l",bounded).query((r,n)->{var x=new LinkedHashMap<String,Object>();x.put("id","memo:"+r.getString(1));x.put("kind","MEMO");x.put("label",r.getString(2));x.put("memoType",r.getString(3));x.put("taskState",r.getString(4)==null?"NONE":r.getString(4));x.put("overdue",r.getBoolean(5));nodes.add(x);return 0;}).list();db.sql("select distinct t.id,t.canonical_name,i.memo_id from tags t join item_tags it on it.tag_id=t.id join memo_items i on i.id=it.memo_item_id where t.owner_id=:o limit :l").param("o",identity.ownerId()).param("l",bounded).query((r,n)->{nodes.add(Map.of("id","tag:"+r.getString(1),"kind","TAG","label",r.getString(2)));edges.add(Map.of("id","memo-tag:"+r.getString(3)+":"+r.getString(1),"source","memo:"+r.getString(3),"target","tag:"+r.getString(1),"kind","MEMO_TAG"));return 0;}).list();return Map.of("nodes",nodes,"edges",edges,"truncated",nodes.size()>=bounded,"projectionVersion",UUID.randomUUID());}
}
